/*
 * Extract the three interesting flags from an SID, however, only set
 * the respective booleans if the flag is set in the SID.
 */
static void
extract_a3_a4_amsdu(guint16 sid, gboolean *a3_present, gboolean *a4_present,
                    gboolean *a_msdu)
{
  if (sid & SID_A3_PRESENT)
    *a3_present = TRUE;
  if (sid & SID_A4_PRESENT)
    *a4_present = TRUE;
  if (sid & SID_A_MSDU)
    *a_msdu = TRUE;
}

static int
wlan_aid_to_str(const address* addr, char* buf, int buf_len)
{
    int ret;

    ret = snprintf(buf, buf_len, "AID 0x%04"PRIx16, *(guint16 *)addr->data);

    return ret + 1;
}

static int
wlan_aid_str_len(const address* addr _U_)
{
    return sizeof("AID 0x0000");
}

