    def getLine(self,keyword):
        res = []
        lines = self.content.split("\n")
        ct =  0 
        linenum = 0

        for line in lines:
            ct +=1
            if keyword in line:
                res.append(line)
                linenum = ct
        if len(res)<2:
            return res, linenum
        pat = re.compile(rf"{re.escape(keyword)}(\.git(?:\s.*)?|(?:\s.*)?)?$")
        res = []
